input.content:
extends CharacterBody2D

# --- Movement parameters ---
const SPEED: float = 250.0      # horizontal speed (pixels / second)
const JUMP_VELOCITY: float = -480.0  # initial jump velocity (negative = up)

# Gravity is pulled from project settings so it stays consistent
# with the physics engine's expectations.
var gravity: float = ProjectSettings.get_setting("physics/2d/default_gravity")


func _physics_process(delta: float) -> void:
	# Apply gravity when not on the floor.
	if not is_on_floor():
		velocity.y += gravity * delta

	# Handle jump — only when standing on the ground.
	if Input.is_action_just_pressed("jump") and is_on_floor():
		velocity.y = JUMP_VELOCITY

	# Horizontal movement (left / right).
	var direction: float = Input.get_axis("move_left", "move_right")
	if direction != 0.0:
		velocity.x = direction * SPEED
	else:
		# Stop quickly when no key is pressed.
		velocity.x = move_toward(velocity.x, 0.0, SPEED)

	# Move_and_slide automatically handles collisions and floor detection.
	move_and_slide()
